// Error Trigger payload: { workflow, execution, url } — job id pattern
// di stage templates: <agent>_<episode> (mis. hook_EP302)
const wf = $input.first().json.workflow?.name ?? '';
const err = $input.first().json.execution?.error?.message ?? 'unknown error';
const map = [
  ['HOOK stage', 'hook'],
  ['Approval Gate', 'nova'],
  ['LEXA', 'lexa'],
  ['PIXEL', 'pixel'],
  ['BOLT', 'bolt'],
  ['AKIRA', 'akira'],
];
const hit = map.find(([needle]) => wf.toLowerCase().includes(needle.toLowerCase()));
const agentId = hit?.[1] ?? 'akira';
// ekstrak episode dari pesan error bila ada, fallback timestamp
const m = err.match(/EP(\d+)/i);
const episode = m ? m[1] : String(Date.now() % 100000);
return [{ json: { agentId, jobId: `${agentId}_EP${episode}`, message: err.slice(0, 120) } }];
